# The user's Kanoa user id for the changes (changedBy); a guest has none and can only look
if not value: return None
return system.kanoa.security.getIDPUserId(value)

# What Combine does (for a user who can change counts), and how a run's calculated waste is worked out when the range has one
tr = lambda s: system.util.translate(s, value['locale'])
parts = []
if value['user']: parts.append(tr("Combine replaces each group of entries with one entry for their total, at the group's last entry."))
if ((value['data'] or {}).get('derived') or []):
	parts.append(tr("Uncoded (calculated) is a run's waste worked out from its infeed and outfeed, as the run has no waste counts. It's one row for the whole run; the chart's Scrap row marks where it happened, by hour."))
	if value['user']: parts.append(tr('Setting a reason records it as one entry.'))
return ' '.join(parts)

customMethods.script:
# The selected rows' entries: a group's by counter, reason, item and work order over its own time (only them, as Combine
# checks), else each entry at its time. The first click turns the button into Confirm Delete
rows = [r for r in self.getChild('tblScrap').props.data if r['sel'] and r['kind'] == 'entries']
if not rows: return
if not self.view.custom.confirmDelete:
	self.view.custom.confirmDelete = True
	return
# A guest has no Kanoa user id to record the change with (its write would fail): say to log in instead
userId = self.view.custom.userId
if not userId or userId <= 0:
	system.kanoa.toast.show({'id': 'scrapEditor', 'type': 'warning', 'message': system.util.translate('Log in to change counts.', self.session.props.locale)})
	return
entries = (self.view.custom.data or {}).get('entries') or []
msgs = []
def remove(r, t0, t1):
	n, msg = system.kanoa.event.deleteCounterEvents({'counterId': r['counterId'], 'startDate': system.date.fromMillis(t0),
		'endDate': system.date.fromMillis(t1 + 1), 'itemStateId': r['itemStateId'], 'itemId': r['itemId'], 'workOrderId': r['workOrderId']}, userId)
	if msg: msgs.append(msg)
for r in rows:
	same = [e for e in entries if r['t0'] <= e['t'] <= r['t1'] and e['counterId'] == r['counterId'] and e['itemStateId'] == r['itemStateId']
		and e['itemId'] == r['itemId'] and e['workOrderId'] == r['workOrderId']]
	if len(same) == r['entries']: remove(r, r['t0'], r['t1'])
	else:
		for t in r['times']: remove(r, t, t)
self.done(msgs)
